import{_ as t,o,c as a,a5 as n}from"./chunks/framework.Bqo7-qSd.js";const u=JSON.parse('{"title":"Choice","description":"","frontmatter":{"title":"Choice","order":7},"headers":[],"relativePath":"en/latest/tutorial/script/choice.md","filePath":"en/latest/tutorial/script/choice.md","lastUpdated":1795484315000}'),i={name:"en/latest/tutorial/script/choice.md"};function s(c,e,r,d,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="choice-jump" tabindex="-1">Choice Jump <a class="header-anchor" href="#choice-jump" aria-label="Permalink to &quot;Choice Jump&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This feature must be used together with the <strong>branch feature</strong>. It configures jump logic inside interactive options: clicking an option jumps to the specified branch. Each <code>choice</code> statement creates one option, and multiple adjacent <code>choice</code> lines are merged into one option group shown together.</p><p>An option can carry a <strong>visibility condition</strong> (<code>if</code>) and a <strong>one-time flag</strong> (<code>once</code>), which covers common needs such as &quot;only show this when affection is high enough&quot; or &quot;ask this only once&quot;.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;option text&quot; -&gt; branch_name [if %variable operator value] [once]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>Option text</td><td>Yes</td><td><code>&quot;Choose coffee&quot;</code></td><td>Option text shown during interaction</td></tr><tr><td>Branch name</td><td>Yes</td><td><code>coffee_choice</code></td><td>Unique identifier of the target branch</td></tr><tr><td><code>if</code> condition</td><td>No</td><td><code>if %love &gt;= 5</code></td><td>Show the option only when the condition holds</td></tr><tr><td><code>once</code></td><td>No</td><td><code>once</code></td><td>Hide the option after it has been picked</td></tr></tbody></table><p><code>if</code> and <code>once</code> may appear in any order, but each at most once. Conditions support the same six comparison operators as <code>if</code> statements, and the value may be a number, string, boolean, or variable.</p><h2 id="usage-examples" tabindex="-1">Usage Examples <a class="header-anchor" href="#usage-examples" aria-label="Permalink to &quot;Usage Examples&quot;">​</a></h2><p>Each option can be written on its own line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Green tea&quot; -&gt; green_tea</span></span>
<span class="line"><span>choice &quot;Black tea&quot; -&gt; black_tea</span></span></code></pre></div><p>Conditional and one-time options:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>choice &quot;Give flowers (+10)&quot; -&gt; gift_flower</span></span>
<span class="line"><span>choice &quot;Give a book (+5)&quot; -&gt; gift_book if %love &gt;= 5</span></span>
<span class="line"><span>choice &quot;(Asked before) Town rumor&quot; -&gt; rumor</span></span>
<span class="line"><span>choice &quot;(Ask once) Mysterious merchant&quot; -&gt; merchant once</span></span>
<span class="line"><span>choice &quot;Give nothing&quot; -&gt; gift_none</span></span></code></pre></div><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>Condition is false</strong>: the option is hidden. If no option in the group is available, execution continues with the statement after the choice group; an empty menu is never shown.</li><li><strong>Missing or type-incompatible condition variable</strong>: treated as false, with a single console warning instead of failing the shot.</li><li><strong><code>once</code> identity</strong>: composed of the choice instruction&#39;s stable key, the target branch&#39;s stable key, and the option index. Translating or rewriting option text does not reset it; reordering options is treated as a different option.</li><li><strong>Rollback and saves</strong>: the usage record is runtime state, restored by &quot;previous line&quot;, checkpoints, and saves; <code>init_dialogue()</code> clears it for a new game.</li><li><strong>Named parameters</strong>: group-level parameters such as <code>[id=...]</code> may only be written on the first option line.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ol><li>The branch name must exactly match a branch identifier in the script. It is case-sensitive and cannot contain spaces or special symbols.</li><li>Option text must be wrapped in English double quotes.</li><li><code>-&gt;</code> is the separator between the option and the branch name and cannot be omitted.</li><li><code>once</code> records the menu item, not the branch: options in different menus that target the same branch do not affect each other.</li></ol>`,17)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
